const $=id=>document.getElementById(id), colors=['#f7a4d4','#c4a1f2','#ef84c4','#ad8ae5','#f8bce2','#d5b4f5','#ee9bdb','#b999ed'];
const time=h=>`${h%12||12}:00 ${h<12?'AM':'PM'}`;
const defaults=h=>h===14?['Play my piano','Study','Make lunch']:h<6?['Read a book','Wind down','Rest']:h<12?['Make breakfast','Study','Go for a walk']:h<17?['Play my piano','Study','Make lunch']:h<21?['Make dinner','Get some exercise','Practice piano']:['Read a book','Listen to music','Wind down'];
const categories=['Work','Health & Body','Social','Fun & Creativity','Home & Admin','Learning','Rest & Reset','Random Challenge'];
const energies=['Low Energy','Medium Energy','High Energy'];
let state={hours:{},picks:{},wheels:{}},hour=14,rotation=0,spinning=false,mode='categories';
try{const data=JSON.parse(localStorage.getItem('daywheel-v1'));if(data&&data.hours&&data.picks){for(let h=0;h<24;h++){if(Array.isArray(data.hours[h])&&data.hours[h].length>0&&data.hours[h].length<=8&&data.hours[h].every(v=>typeof v==='string'&&v.trim()&&v.length<=36))state.hours[h]=data.hours[h];if(typeof data.picks[h]==='string')state.picks[h]=data.picks[h].slice(0,36)}}}catch{}
try{const saved=JSON.parse(localStorage.getItem('daywheel-modes-v1'));if(saved&&typeof saved==='object')for(const [key,list] of Object.entries(saved)){if(/^(categories|energy)-([0-9]|1[0-9]|2[0-3])$/.test(key)&&Array.isArray(list)&&list.length>0&&list.length<=8&&list.every(v=>typeof v==='string'&&v.trim()&&v.length<=36))state.wheels[key]=list}}catch{}
function save(){try{localStorage.setItem('daywheel-v1',JSON.stringify(state));localStorage.setItem('daywheel-modes-v1',JSON.stringify(state.wheels))}catch{$('limit').textContent='Browser storage is unavailable. Changes last for this visit.'}}
function activities(){if(mode==='activities')return state.hours[hour]||(state.hours[hour]=defaults(hour));const key=mode+'-'+hour;return state.wheels[key]||(state.wheels[key]=[...(mode==='energy'?energies:categories)])}
for(let h=0;h<24;h++){const opt=document.createElement('option');opt.value=h;opt.textContent=time(h);$('hour').append(opt)}$('hour').value=hour;
const date=new Date();$('date').append(document.createTextNode(date.toLocaleDateString(undefined,{weekday:'long'})));const dateStrong=document.createElement('strong');dateStrong.textContent=date.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'});$('date').append(dateStrong);
function svgEl(type,attrs){const el=document.createElementNS('http://www.w3.org/2000/svg',type);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);return el}
function draw(){const list=activities(),n=list.length,wheel=$('wheel');wheel.replaceChildren();list.forEach((label,i)=>{const start=(i/n*360-90)*Math.PI/180,end=((i+1)/n*360-90)*Math.PI/180,mid=(start+end)/2;const path=n===1?svgEl('circle',{cx:210,cy:210,r:210,fill:colors[i]}):svgEl('path',{d:`M210 210 L${210+210*Math.cos(start)} ${210+210*Math.sin(start)} A210 210 0 ${n===2?0:(end-start>Math.PI?1:0)} 1 ${210+210*Math.cos(end)} ${210+210*Math.sin(end)} Z`,fill:colors[i],stroke:'#fff','stroke-width':2});wheel.append(path);const tx=210+128*Math.cos(mid),ty=210+128*Math.sin(mid),text=svgEl('text',{x:tx,y:ty,'text-anchor':'middle','dominant-baseline':'middle',fill:'#172029','font-family':'DM Sans, sans-serif','font-weight':600,'font-size':n>5?13:16});const words=label.split(' '),lines=[];let line='';for(const word of words){if((line+' '+word).trim().length>13&&line){lines.push(line);line=word}else line=(line+' '+word).trim()}if(line)lines.push(line);lines.slice(0,3).forEach((part,j)=>{const span=svgEl('tspan',{x:tx,dy:j?19:-(Math.min(lines.length,3)-1)*9.5});span.textContent=part.length>15?part.slice(0,14)+'…':part;text.append(span)});wheel.append(text)});wheel.setAttribute('aria-label',`Activity wheel: ${list.join(', ')}`);$('count').textContent=`${n} possibilit${n===1?'y':'ies'}`}
function render(){const list=activities();$('activities').replaceChildren();list.forEach((value,i)=>{const row=document.createElement('div');row.className='activity';const dot=document.createElement('span');dot.className='swatch';dot.style.background=colors[i];const input=document.createElement('input');input.value=value;input.maxLength=36;input.setAttribute('aria-label',`Activity ${i+1}`);input.addEventListener('change',()=>{list[i]=input.value.trim()||value;input.value=list[i];save();draw()});const remove=document.createElement('button');remove.className='remove';remove.textContent='×';remove.setAttribute('aria-label',`Remove ${value}`);remove.disabled=list.length===1;remove.onclick=()=>{list.splice(i,1);save();render()};row.append(dot,input,remove);$('activities').append(row)});$('new-activity').disabled=list.length>=8;$('add-form').querySelector('button').disabled=list.length>=8;$('wheel-time').textContent=time(hour);$('result-label').textContent=state.picks[hour]?`YOUR PICK FOR ${time(hour)}`:'YOUR NEXT CHAPTER';$('result').textContent=state.picks[hour]||'What will it be?';draw();renderDay();updateBudget()}
function renderDay(){const entries=Object.entries(state.picks).sort((a,b)=>Number(a[0])-Number(b[0]));$('planned-count').textContent=`${entries.length} hour${entries.length===1?'':'s'} decided`;$('timeline').replaceChildren();if(!entries.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='Your picks will appear here as you spin.';$('timeline').append(empty)}entries.forEach(([h,activity])=>{const button=document.createElement('button');button.className='pick';const small=document.createElement('small');small.textContent=time(Number(h));const strong=document.createElement('strong');strong.textContent=activity;button.append(small,strong);button.onclick=()=>{if(!spinning){hour=Number(h);$('hour').value=hour;resetRotation();render()}};$('timeline').append(button)})}
function resetRotation(){rotation=0;$('wheel').style.transition='none';$('wheel').style.transform='rotate(0deg)';void $('wheel').getBoundingClientRect();$('wheel').style.transition=''}
$('hour').onchange=()=>{hour=Number($('hour').value);resetRotation();render()};
$('add-form').onsubmit=e=>{e.preventDefault();if(spinning)return;const val=$('new-activity').value.trim();if(val&&activities().length<8){activities().push(val);$('new-activity').value='';save();resetRotation();render();$('new-activity').focus()}};

const budgetKey='daywheel-spin-times-v1',windowMs=60*60*1000;
function spinTimes(now=Date.now()){const raw=localStorage.getItem(budgetKey);const parsed=raw?JSON.parse(raw):[];if(!Array.isArray(parsed)||!parsed.every(Number.isFinite))throw Error('Invalid spin history');return parsed.filter(t=>t>now-windowMs).sort((a,b)=>a-b)}
function updateBudget(){try{const times=spinTimes(),left=Math.max(0,3-times.length);$('spin-budget').textContent=left?left+' of 3 spins available':'All 3 spins used. Next spin at '+new Date(times[0]+windowMs).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})+'.';$('spin').disabled=spinning||!left}catch{$('spin-budget').textContent='Enable browser storage to use the hourly spin limit.';$('spin').disabled=true}}
function positionWinner(){const rect=$('wheel').getBoundingClientRect(),dialog=$('winner');dialog.style.left=Math.max(16,Math.min(innerWidth-dialog.offsetWidth-16,rect.left+rect.width/2-dialog.offsetWidth/2))+'px';dialog.style.top=Math.max(16,Math.min(innerHeight-dialog.offsetHeight-16,rect.top+rect.height/2-dialog.offsetHeight/2))+'px'}
$('close-winner').onclick=()=>$('winner').close();
$('winner').addEventListener('close',()=>$('spin').disabled?$('mode').focus():$('spin').focus());
window.addEventListener('resize',()=>{if($('winner').open)positionWinner()});
window.addEventListener('scroll',()=>{if($('winner').open)positionWinner()});
$('mode').onchange=()=>{mode=$('mode').value;resetRotation();render()};
async function reserveSpin(){const reserve=()=>{const times=spinTimes();if(times.length>=3)return false;times.push(Date.now());localStorage.setItem(budgetKey,JSON.stringify(times));return true};return navigator.locks? navigator.locks.request('daywheel-spin-budget',reserve):reserve()}
$('spin').onclick=async()=>{if(spinning)return;spinning=true;$('spin').disabled=true;let allowed=false;try{allowed=await reserveSpin()}catch{}if(!allowed){spinning=false;updateBudget();return}const list=[...activities()],chosen=Math.floor(Math.random()*list.length),target=360-(chosen+.5)*360/list.length;rotation+=360*5+((target-rotation%360+360)%360);document.querySelectorAll('input,select,button').forEach(el=>el.disabled=true);$('spin').textContent='Finding your next chapter…';$('result').textContent='A little suspense…';$('wheel').style.transform='rotate('+rotation+'deg)';setTimeout(()=>{state.picks[hour]=list[chosen];save();spinning=false;document.querySelectorAll('input,select,button').forEach(el=>el.disabled=false);$('spin').innerHTML='Spin again <span aria-hidden="true">↗</span>';render();$('winner-title').textContent=list[chosen];$('winner-time').textContent='Your pick for '+time(hour);$('winner').showModal();positionWinner();$('close-winner').focus()},matchMedia('(prefers-reduced-motion: reduce)').matches?100:4600)};
window.addEventListener('storage',event=>{if(event.key===budgetKey)updateBudget()});
setInterval(updateBudget,1000);
render();
